#include <iostream>

double average(double a, double b, double c)
{
    double sum{ a + b + c };
    return sum / 3;
}

double spread(double coldest, double warmest)
{
    return warmest - coldest;
}

int main()
{
    double a{};
    double b{};
    double c{};
    std::cin >> a >> b >> c;

    std::cout << "Average: " << average(a, b, c) << '\n';
    std::cout << "Spread: " << spread(a, c) << '\n';
    return 0;
}
